import {RanchRenderer} from './ranch-renderer.js';
import * as T from 'three';
import {OrbitControls} from '/vendor/OrbitControls.js';
import {DEFAULTS,MARKET_STYLES,normalize,simulateMarket,createMarketScene,DRESSING_DEFAULTS,MARKET_SCENE_VERSION,marketUrl} from './market-scene.js';
const $=id=>document.getElementById(id),host=$('market-viewport');
const scene=new T.Scene();scene.background=new T.Color('#e7ebd9');
const renderer=new RanchRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.append(renderer.domElement);
const camera=new T.PerspectiveCamera(38,1,.1,12000),orbit=new OrbitControls(camera,renderer.domElement);orbit.maxPolarAngle=Math.PI*.47;orbit.minDistance=8;orbit.maxDistance=10000;orbit.enableDamping=true;
scene.add(new T.HemisphereLight('#fff8df','#768963',2));const sun=new T.DirectionalLight('#ffefd3',2.6);sun.position.set(-40,65,30);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-16,right:16,top:16,bottom:-16,near:1,far:240});sun.shadow.normalBias=.025;sun.shadow.bias=-.00015;scene.add(sun);
let config={...DEFAULTS},run,time=360,playing=false,last=0,world,actors=[],roofs=[],labels=[],ownGoods=[],cutaway=false,viewMode='market',selected='';
let gridLines,showGrid=false,art,roofMode='solid',dressing={...DRESSING_DEFAULTS};
const fromScene=location.pathname.startsWith('/scene-generator'),params=new URLSearchParams(location.search);
for(const key of ['style','seed','bays','spacing','setting'])if(params.has(key))config[key]=['seed','bays'].includes(key)?Number(params.get(key)):params.get(key);
try{config=normalize(config)}catch{config={...DEFAULTS}}
if(fromScene){document.querySelector('.brand strong').textContent='Scene Generator · Marketplace';document.title='Marketplace · Scene Generator';}
function dress(){if(!art)return;for(const k of ['work','life','landscape'])art.layers[k].visible=dressing[k];art.layers.life.visible=dressing.life&&config.day===6&&time>=540&&time<960;art.setMaterials(dressing.materials);}
function roofsMode(mode){roofMode=mode;cutaway=mode==='cutaway';art.setRoofMode(mode);$('market-roofs').value=mode;$('cutaway-market').textContent=cutaway?'Restore roofs':'Cut away roofs';$('cutaway-market').setAttribute('aria-pressed',String(cutaway));}

function clearWorld(){if(!world)return;scene.remove(world);const materials=new Set();world.traverse(o=>{o.geometry?.dispose();if(o.material)materials.add(o.material);});for(const m of materials)m.dispose();art?.grain?.dispose();art?.disposeMaterials();}
function build(){
 scene.background.set(config.weather==='rain'?'#d3deda':'#e9eddf');sun.intensity=config.weather==='rain'?1.2:2.6;
 clearWorld();art=createMarketScene(T,run);({world,actors,roofs,ownGoods,gridLines}=art);scene.add(world);roofsMode(run.world.profile.view.roofMode);dress();gridLines.visible=showGrid;$('view-intent').textContent=run.world.profile.view.intent;$('other-market-entry').href=marketUrl(fromScene?'/market':'/scene-generator',config);$('other-market-entry').textContent=fromScene?'Open this market in Market Day':'Open this market in Scene Generator';
 $('inspect-place').replaceChildren(new Option('Choose a place',''),new Option('Drop-off','drop'),new Option('Shared storage','store'),...run.world.stalls.map((s,i)=>new Option(`${i+1}. ${s.trade} · ${s.indoor?'inside':'outside'}`,s.id)));
 $('layout-summary').textContent=`Seed ${config.seed} · ${run.world.stalls.length} irregular plots · ${run.world.halls.length} covered shops. New plots join the lanes without moving existing booths.`;
 $('bays').value=String(config.bays);$('style').value=config.style;$('spacing').value=config.spacing;describeStyle();$('style-caption').textContent=MARKET_STYLES[config.style].name.toUpperCase();$('grow-market').disabled=config.bays>=8;$('week-label').textContent=config.week;$('market-seed').value=config.seed;fit();
}
function fit(mode=viewMode){
 viewMode=mode;if(art)art.journey.visible=mode==='journey';const tile=run.world.tile,scale=tile.display.scale,view=run.world.profile.view,b={...run.world.bounds};if(mode==='journey')b.minZ=run.world.nodes.find(n=>n.id==='home').z-5;
 const bounds=mode==='tile'?{minX:-12,maxX:12,minZ:-12*Math.sqrt(3)/2,maxZ:12*Math.sqrt(3)/2}:{minX:(b.minX-tile.cx)*scale,maxX:(b.maxX-tile.cx)*scale,minZ:(b.minZ-tile.cz)*scale,maxZ:(b.maxZ-tile.cz)*scale};
 const center=new T.Vector3((bounds.minX+bounds.maxX)/2,.3,(bounds.minZ+bounds.maxZ)/2),az=view.azimuth*Math.PI/180,el=view.elevation*Math.PI/180,dir=mode==='plan'?new T.Vector3(.001,1,.001).normalize():new T.Vector3(Math.cos(az)*Math.cos(el),Math.sin(el),Math.sin(az)*Math.cos(el)),right=new T.Vector3().crossVectors(new T.Vector3(0,1,0),dir).normalize(),up=new T.Vector3().crossVectors(dir,right),v=Math.tan(camera.fov*Math.PI/360);let distance=0;
 for(const x of [bounds.minX-.5,bounds.maxX+.5])for(const z of [bounds.minZ-.5,bounds.maxZ+.5])for(const y of [-.45,2]){const p=new T.Vector3(x,y,z).sub(center);distance=Math.max(distance,p.dot(dir)+Math.max(Math.abs(p.dot(right))/(v*camera.aspect),Math.abs(p.dot(up))/v));}camera.position.copy(center).addScaledVector(dir,distance*1.04);orbit.target.copy(center);orbit.update();if(run)draw();
}

function clock(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function draw(){if(!run)return;const f=run.frames[Math.min(run.frames.length-1,Math.floor(time-360))];
 ownGoods.forEach((g,i)=>g.visible=i<Math.ceil(f.boothStock/8*ownGoods.length));
 dress();for(const p of f.people){actors[p.id].g.visible=viewMode==='journey'||run.world.tile.corners.every((a,i)=>{const b=run.world.tile.corners[(i+1)%6];return (b.x-a.x)*(p.position.z-a.z)-(b.z-a.z)*(p.position.x-a.x)>=0});actors[p.id].g.position.set(p.position.x+p.id*.7,.12,p.position.z);actors[p.id].basket.visible=p.bag>0||p.carry>0||/Carrying|Going to/.test(p.state);}
 const phase=config.day!==6?'Market closed':time<540?'Preparing for market':time<960?'Market open':f.returned===config.people?'Home again':'Market closed';
 $('market-clock').textContent=clock(time)+' · '+phase;$('market-caption').textContent=`Week ${config.week} · ${run.world.stalls.length} booths · ${config.weather==='rain'?'Rainy':'Clear'} · ${config.distance} m from home`;
 $('time-label').textContent=clock(time);$('market-time').value=time;
 $('market-totals').innerHTML=`<span><b>${f.sold}</b>units sold / ${config.purpose==='buy'?0:24}</span><span><b>${f.bought}</b>shopping / ${config.purpose==='sell'?0:6}</span><span><b>${f.boothStock} + ${f.reserve}</b>booth + reserve</span><span><b>${f.missed}</b>unserved demand</span><span><b>${f.stored}</b>purchases in storage</span><span><b>${f.purchasesHome}</b>purchases brought home</span>`;
 $('market-people').replaceChildren(...f.people.map(p=>{const d=document.createElement('div');d.className='person';const b=document.createElement('b'),i=document.createElement('i');i.style.background=p.id?'#cc954c':'#4d8196';b.append(i,p.name);d.append(b,document.createTextNode(p.state));return d;}));
 const hour=Math.floor(time/60)*60,events=run.events.filter(e=>e.minute>=hour&&e.minute<=time);$('market-events').replaceChildren(...(events.length?events:[{minute:hour,text:f.open?'Trading and errands continue.':'No new activity this hour.'}]).map(e=>{const li=document.createElement('li');li.textContent=clock(e.minute)+' · '+e.text;return li;}));
 $('play-market').textContent=playing?'Pause':time>=1200?'Replay day':'Play day';
 window.RanchView?.changed();
}
function describeStyle(){const p=MARKET_STYLES[$('style').value];$('style-description').textContent=p.description;$('style-source').href=p.source;$('style-source').textContent=p.origin+' · reference ↗';}
function readConfig(){const next={...config};for(const key of ['purpose','people','day','departure','distance','setting','weather','style','spacing','bays'])next[key]=['people','day','departure','distance','bays'].includes(key)?Number($(key).value):$(key).value;return normalize(next);}
function update(next,{play=false,message='Day ready. Play or step through each hour.'}={}){try{const result=simulateMarket(next);config=result.config;run=result;time=play?360:660;playing=play;build();draw();$('market-notice').textContent=message;return true;}catch(e){playing=false;$('play-market').textContent='Play day';$('market-notice').textContent=e.message;return false;}}
function fromForm(extra={},options={}){try{return update({...readConfig(),...extra},options);}catch(e){$('market-notice').textContent=e.message;return false;}}
function closeOnMobile(){if(innerWidth<800)window.RanchDrawers?.close();}
for(const key of ['purpose','people','day','departure','distance','setting','weather','style','spacing','bays'])$(key).onchange=()=>{describeStyle();playing=false;$('play-market').textContent='Play day';$('market-notice').textContent='Settings changed. Generate market to preview, or Go to market to start the day.';};
 $('preview-market').onclick=()=>{if(fromForm({}, {message:'Market generated. Choose Go to market when ready.'}))closeOnMobile();};
 $('run-market').onclick=()=>{if(fromForm({}, {play:true,message:'The day is running. Open the drawer to pause, inspect, or advance an hour.'}))closeOnMobile();};
 $('play-market').onclick=()=>{if(time>=1200)time=360;playing=!playing;draw();};$('step-market').onclick=()=>{playing=false;time=Math.min(1200,(Math.floor(time/60)+1)*60);draw();};$('market-time').oninput=()=>{playing=false;time=Number($('market-time').value);draw();};
 $('grow-market').onclick=()=>{if(config.bays<8)fromForm({bays:config.bays+1},{message:'Four new plots joined the market. Existing booths stayed in place. The day has reset.'});};
 $('fresh-market').onclick=()=>{if(fromForm({seed:crypto.getRandomValues(new Uint32Array(1))[0]||1},{message:'Fresh layout generated. The day has reset.'}))closeOnMobile();};
 $('rebuild-market').onclick=()=>{if(fromForm({seed:Number($('market-seed').value)}))closeOnMobile();};
 $('next-market').onclick=()=>{if(fromForm({week:config.week+1,day:6},{message:'Next Saturday. Same marketplace, fresh sale stock and shopping list.'}))$('day').value='6';};
 $('grid-market').onclick=()=>{showGrid=!showGrid;gridLines.visible=showGrid;$('grid-market').setAttribute('aria-pressed',String(showGrid));$('grid-market').textContent=showGrid?'Hide irregular grid':'Show irregular grid';};
 $('fit-market').onclick=()=>{fit('market');closeOnMobile();};$('route-market').onclick=()=>{fit('journey');closeOnMobile();};$('top-market').onclick=()=>{fit('plan');closeOnMobile();};$('cutaway-market').onclick=()=>roofsMode(cutaway?'solid':'cutaway');
 $('market-roofs').onchange=e=>roofsMode(e.target.value);$('recommended-market').onclick=()=>{roofsMode(run.world.profile.view.roofMode);fit('market');closeOnMobile()};$('tile-market').onclick=()=>{fit('tile');closeOnMobile()};for(const k of Object.keys(dressing))$('dress-'+k).onchange=e=>{dressing[k]=e.target.checked;dress()};

 $('inspect-place').onchange=e=>{selected=e.target.value;const n=run.world.nodes.find(n=>n.id===selected);if(!n)return;const s=run.world.stalls.find(s=>s.id===selected);$('place-description').textContent=s?`${s.trade}. ${s.indoor?'Inside a covered market hall':'Outdoor canopy'}. Faces a connected lane on an irregular plot. ${s.id===run.world.booth?'Abbie staffs this booth; sales stop while fetching stock.':''}`:selected==='drop'?'Arrival and unloading point. Visitors walk their goods onward to storage.':'Shared storage for reserve sale stock, personal belongings, and purchased goods.';const scale=run.world.tile.display.scale,x=(n.x-run.world.tile.cx)*scale,z=(n.z-run.world.tile.cz)*scale;orbit.target.set(x,0,z);camera.position.set(x+3,4,z+4);orbit.update();};
 $('save-market').onclick=()=>{try{localStorage.setItem('ranch-market-v2',JSON.stringify({version:2,config,time,cutaway,roofMode,dressing}));$('market-notice').textContent='Day and playback position saved on this device.';}catch{$('market-notice').textContent='Device storage unavailable; the day has not been saved.';}};
 $('load-market').onclick=()=>{try{const saved=JSON.parse(localStorage.getItem('ranch-market-v2')||localStorage.getItem('ranch-market-v1'));if(![1,2].includes(saved?.version)||!Number.isFinite(saved.time)||saved.time<360||saved.time>1200)throw Error('No valid saved market day on this device.');if(!update(normalize(saved.config)))return;for(const key of ['purpose','people','day','departure','distance','setting','weather','style','spacing','bays'])$(key).value=String(config[key]);time=saved.time;dressing={...DRESSING_DEFAULTS,...saved.dressing};for(const k of Object.keys(DRESSING_DEFAULTS))$('dress-'+k).checked=dressing[k];roofsMode(['solid','xray','cutaway'].includes(saved.roofMode)?saved.roofMode:saved.cutaway?'cutaway':'solid');$('cutaway-market').textContent=cutaway?'Roofs cut away':'Roofs visible';$('cutaway-market').setAttribute('aria-pressed',String(cutaway));draw();$('market-notice').textContent=saved.version===1?'Earlier visit recomputed on the new irregular market.':'Saved day restored.';closeOnMobile();}catch(e){$('market-notice').textContent=e.message;}};
 new ResizeObserver(()=>{const width=host.clientWidth,height=host.clientHeight;if(!width||!height)return;renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();if(run)fit();}).observe(host);
 orbit.addEventListener('end',()=>window.RanchView?.changed());
 let pointerStart;renderer.domElement.addEventListener('pointerdown',e=>pointerStart=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>6)return;const rect=renderer.domElement.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),camera);for(const hit of ray.intersectObjects(world.children,true)){let o=hit.object;while(o&&!o.userData.place)o=o.parent;if(o?.userData.place){$('inspect-place').value=o.userData.place;$('inspect-place').onchange({target:$('inspect-place')});window.RanchDrawers?.open();$('inspect-place').scrollIntoView({block:'center'});break;}}});
 window.RanchView?.register('market',()=>({generatorVersion:MARKET_SCENE_VERSION,entry:fromScene?'scene-generator':'market',dressing,roofMode,config,minute:time,playing,cutaway,showGrid,gridKind:run?.world.gridKind,selected,summary:run?.summary,camera:camera.position.toArray(),target:orbit.target.toArray()}),()=>renderer.render(scene,camera));
 update(config);if(innerWidth<800){const ready=()=>{if(window.RanchDrawers)window.RanchDrawers.close();else setTimeout(ready,50);};ready();}
 function animate(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(playing){const previous=Math.floor(time);time=Math.min(1200,time+dt*Number($('market-speed').value));if(time>=1200)playing=false;if(previous!==Math.floor(time))draw();}orbit.update();renderer.render(scene,camera);requestAnimationFrame(animate);}requestAnimationFrame(animate);


